namespace CheckoutPricing.Domain;

public static class LoyaltyDiscount
{
    private const int CeilingPoints = 10;

    public static int PayableCents(LoyaltyTier tier, int subtotalCents)
    {
        var baseRate = tier switch
        {
            LoyaltyTier.Bronze => 5,
            LoyaltyTier.Silver => 7,
            LoyaltyTier.Gold => 9,
        };

        var bonus = subtotalCents switch
        {
            < 5000 => 0,
            < 20000 => 1,
            _ => 3,
        };

        var effectiveRate = Math.Min(baseRate + bonus, CeilingPoints);
        var discountCents = subtotalCents * effectiveRate / 100;

        return subtotalCents - discountCents;
    }
}
